/**
 * Keshavarz20 Merchant Return Policy Schema
 * Version: 4.0 - evidence-aligned
 *
 * Policy principle:
 * - The public policy is conditional (mismatch/approved returns), not a blanket 1-day return right.
 * - Therefore we expose the real policy URL globally and do not invent merchantReturnDays,
 *   free-return fees, or a universal refund/exchange type.
 */

function k20_merchant_return_policy_id() {
    return 'https://keshavarz20.com/refund_returns/#merchant-return-policy';
}

function k20_merchant_return_policy_object() {
    return array(
        '@type'              => 'MerchantReturnPolicy',
        '@id'                => k20_merchant_return_policy_id(),
        'merchantReturnLink' => 'https://keshavarz20.com/refund_returns/',
    );
}

/* Attach the standard store policy to the Organization graph site-wide. */
add_filter( 'wpseo_schema_organization', function ( $data, $context ) {
    if ( ! is_array( $data ) ) {
        return $data;
    }

    $data['hasMerchantReturnPolicy'] = k20_merchant_return_policy_object();
    return $data;
}, 20, 2 );

/*
 * When WooCommerce outputs an Offer, reference the same global policy by @id only.
 * This avoids creating a product-specific policy that could override the real store policy.
 */
add_filter( 'woocommerce_structured_data_product_offer', function ( $offer, $product ) {
    if ( ! is_array( $offer ) ) {
        return $offer;
    }

    $offer['hasMerchantReturnPolicy'] = array(
        '@id' => k20_merchant_return_policy_id(),
    );
    return $offer;
}, 9999, 2 );

add_filter( 'wpseo_schema_offer', function ( $offer, $variation, $product ) {
    if ( ! is_array( $offer ) ) {
        return $offer;
    }

    $offer['hasMerchantReturnPolicy'] = array(
        '@id' => k20_merchant_return_policy_id(),
    );
    return $offer;
}, 9999, 3 );

/* Fallback for Offer nodes generated by other schema integrations. */
add_filter( 'wpseo_schema_graph', function ( $graph, $context ) {
    if ( ! function_exists( 'is_product' ) || ! is_product() || ! is_array( $graph ) ) {
        return $graph;
    }

    $scan = function ( &$node ) use ( &$scan ) {
        if ( ! is_array( $node ) ) {
            return;
        }

        if ( isset( $node['@type'] ) ) {
            $types = is_array( $node['@type'] ) ? $node['@type'] : array( $node['@type'] );
            if ( in_array( 'Offer', $types, true ) ) {
                $node['hasMerchantReturnPolicy'] = array(
                    '@id' => k20_merchant_return_policy_id(),
                );
            }
        }

        foreach ( $node as &$value ) {
            if ( is_array( $value ) ) {
                $scan( $value );
            }
        }
        unset( $value );
    };

    foreach ( $graph as &$piece ) {
        $scan( $piece );
    }
    unset( $piece );

    return $graph;
}, 9999, 2 );

/*
 * Keshavarz20 Global Shipping Policy Schema
 * Version 2
 *
 * آماده سازی: 1 تا 3 روز
 * حمل پس از تحویل به باربری: 1 تا 5 روز
 * هزینه حمل: متغیر و بر عهده مشتری
 */


/*
 * -----------------------------------------
 * 1. اطلاعات اصلی سرویس ارسال کشاورز بیست
 * -----------------------------------------
 */

function keshavarz20_get_shipping_service() {

    return array(

        '@type' => 'ShippingService',

        '@id' =>
            'https://keshavarz20.com/#shipping-service',

        'name' =>
            'سرویس ارسال سفارشات کشاورز بیست',

        'description' =>
            'آماده سازی سفارش های کشاورز بیست معمولاً 1 تا 3 روز زمان می برد. پس از تحویل سفارش به شرکت حمل، زمان حمل بسته به مقصد و مسیر معمولاً بین 1 تا 5 روز است. در مسیرهای مستقیم باربری، حمل معمولاً حداکثر حدود 48 ساعت زمان می برد. در مقصدهایی که نیاز به انتقال بار بین چند باربری وجود دارد، زمان حمل ممکن است تا حدود 5 روز افزایش پیدا کند. هزینه حمل ثابت نیست و بر اساس نوع کالا، وزن، حجم، مقصد، روش حمل و تعداد مراحل باربری محاسبه شده و بر عهده مشتری است.',

        'fulfillmentType' =>
            'https://schema.org/FulfillmentTypeDelivery',


        /*
         * زمان آماده سازی سفارش
         * 1 تا 3 روز
         */

        'handlingTime' => array(

            '@type' => 'ServicePeriod',

            'duration' => array(

                '@type' => 'QuantitativeValue',

                'minValue' => 1,

                'maxValue' => 3,

                'unitCode' => 'DAY',
            ),
        ),


        /*
         * شرایط ارسال داخل ایران
         */

        'shippingConditions' => array(

            '@type' => 'ShippingConditions',


            /*
             * مقصد ارسال
             */

            'shippingDestination' => array(

                '@type' => 'DefinedRegion',

                'addressCountry' => 'IR',
            ),


            /*
             * مبدا ارسال
             */

            'shippingOrigin' => array(

                '@type' => 'DefinedRegion',

                'addressCountry' => 'IR',
            ),


            /*
             * زمان حمل پس از تحویل به حامل
             * حداقل 1 روز
             * حداکثر 5 روز
             */

            'transitTime' => array(

                '@type' => 'ServicePeriod',

                'duration' => array(

                    '@type' => 'QuantitativeValue',

                    'minValue' => 1,

                    'maxValue' => 5,

                    'unitCode' => 'DAY',
                ),
            ),
        ),
    );
}


/*
 * -----------------------------------------
 * 2. اضافه کردن سیاست ارسال سراسری
 * به Organization
 * -----------------------------------------
 */

add_filter(
    'wpseo_schema_organization',
    'keshavarz20_add_shipping_service_to_organization',
    30,
    2
);

function keshavarz20_add_shipping_service_to_organization(
    $data,
    $context
) {

    $data['hasShippingService'] =
        keshavarz20_get_shipping_service();

    return $data;
}


/*
 * -----------------------------------------
 * 3. مرجع OfferShippingDetails
 *
 * این بخش نرخ حمل ساختگی ایجاد نمی کند.
 * Offer فقط به سیاست عمومی فروشگاه متصل می شود.
 * -----------------------------------------
 */

function keshavarz20_get_shipping_reference() {

    return array(

        '@type' => 'OfferShippingDetails',

        'hasShippingService' => array(

            '@id' =>
                'https://keshavarz20.com/#shipping-service',
        ),
    );
}


/*
 * -----------------------------------------
 * 4. WooCommerce Offer
 * -----------------------------------------
 */

add_filter(
    'woocommerce_structured_data_product_offer',
    'keshavarz20_add_shipping_to_wc_offer',
    9999,
    2
);

function keshavarz20_add_shipping_to_wc_offer(
    $offer,
    $product
) {

    if ( ! is_array( $offer ) ) {
        return $offer;
    }

    /*
     * اگر قبلاً سیاست اختصاصی برای محصول وجود دارد
     * آن را خراب نمی کنیم.
     */

    if ( empty( $offer['shippingDetails'] ) ) {

        $offer['shippingDetails'] =
            keshavarz20_get_shipping_reference();
    }

    return $offer;
}


/*
 * -----------------------------------------
 * 5. Yoast Offer
