 */

add_filter(
    'wpseo_schema_offer',
    'keshavarz20_add_shipping_to_yoast_offer',
    9999,
    3
);

function keshavarz20_add_shipping_to_yoast_offer(
    $offer,
    $variation,
    $product
) {

    if ( ! is_array( $offer ) ) {
        return $offer;
    }

    if ( empty( $offer['shippingDetails'] ) ) {

        $offer['shippingDetails'] =
            keshavarz20_get_shipping_reference();
    }

    return $offer;
}


/*
 * -----------------------------------------
 * 6. Fallback روی Graph نهایی Yoast
 *
 * همان روشی که برای Return Policy
 * روی سایت جواب داد.
 * -----------------------------------------
 */

add_filter(
    'wpseo_schema_graph',
    'keshavarz20_shipping_graph_fallback',
    9999,
    2
);

function keshavarz20_shipping_graph_fallback(
    $graph,
    $context
) {

    if (
        ! function_exists( 'is_product' ) ||
        ! is_product()
    ) {
        return $graph;
    }

    if ( ! is_array( $graph ) ) {
        return $graph;
    }

    foreach ( $graph as &$piece ) {

        keshavarz20_scan_schema_for_shipping_offers(
            $piece
        );
    }

    unset( $piece );

    return $graph;
}


/*
 * -----------------------------------------
 * 7. پیدا کردن تمام Offerها در Schema
 * -----------------------------------------
 */

function keshavarz20_scan_schema_for_shipping_offers(
    &$node
) {

    if ( ! is_array( $node ) ) {
        return;
    }


    if ( isset( $node['@type'] ) ) {

        $types = is_array( $node['@type'] )
            ? $node['@type']
            : array( $node['@type'] );


        if ( in_array( 'Offer', $types, true ) ) {

            /*
             * اگر Offer خودش shippingDetails
             * اختصاصی ندارد، سیاست عمومی را وصل می کنیم.
             */

            if ( empty( $node['shippingDetails'] ) ) {

                $node['shippingDetails'] =
                    keshavarz20_get_shipping_reference();
            }
        }
    }


    /*
     * جستجوی بازگشتی در تمام بخش های Schema
     */

    foreach ( $node as &$value ) {

        if ( is_array( $value ) ) {

            keshavarz20_scan_schema_for_shipping_offers(
                $value
            );
        }
    }

    unset( $value );
}

/*
 * Keshavarz20 Real WooCommerce Reviews -> Yoast Product Schema
 *
 * فقط دیدگاه‌های تاییدشده واقعی ووکامرس را استفاده می‌کند.
 * اگر Yoast خودش review / aggregateRating را ساخته باشد،
 * هیچ چیزی را بازنویسی یا تکراری نمی‌کند.
 */

add_filter(
    'wpseo_schema_product',
    'keshavarz20_add_real_reviews_to_product_schema',
    99
);

function keshavarz20_add_real_reviews_to_product_schema( $data ) {

    if (
        ! function_exists( 'is_product' ) ||
        ! is_product() ||
        ! function_exists( 'wc_get_product' )
    ) {
        return $data;
    }

    $product_id = get_queried_object_id();

    if ( ! $product_id ) {
        return $data;
    }

    $product = wc_get_product( $product_id );

    if ( ! $product ) {
        return $data;
    }

    /*
     * داده‌های واقعی ذخیره‌شده توسط WooCommerce
     */
    $rating_count   = (int) $product->get_rating_count();
    $review_count   = (int) $product->get_review_count();
    $average_rating = (float) $product->get_average_rating();

    /*
     * محصول هیچ امتیاز واقعی ندارد:
     * هیچ Schema ساختگی تولید نشود.
     */
    if (
        $rating_count < 1 ||
        $average_rating <= 0
    ) {
        return $data;
    }

    /*
     * Aggregate Rating
     *
     * فقط در صورتی اضافه می‌شود که Yoast
     * خودش قبلاً aggregateRating نساخته باشد.
     */
    if ( empty( $data['aggregateRating'] ) ) {

        $aggregate_rating = array(
            '@type'       => 'AggregateRating',
            'ratingValue' => round(
                $average_rating,
                2
            ),
            'ratingCount' => $rating_count,
            'bestRating'  => 5,
            'worstRating' => 1,
        );

        /*
         * reviewCount فقط وقتی واقعاً Review وجود دارد.
         */
        if ( $review_count > 0 ) {
            $aggregate_rating['reviewCount'] =
                $review_count;
        }

        $data['aggregateRating'] =
            $aggregate_rating;
    }

    /*
     * اگر Yoast خودش Reviewها را ساخته،
     * دیگر چیزی اضافه نکن.
     */
    if ( ! empty( $data['review'] ) ) {
        return $data;
    }

    /*
     * حداکثر 5 دیدگاه اخیر:
     *
     * - تاییدشده
     * - مربوط به همین محصول
     * - دارای Rating واقعی
     * - دیدگاه اصلی، نه پاسخ مدیر
     */
    $comments = get_comments(
        array(
            'post_id' => $product_id,
            'status'  => 'approve',
            'parent'  => 0,
            'number'  => 5,
            'orderby' => 'comment_date_gmt',
            'order'   => 'DESC',

            'meta_query' => array(
                array(
                    'key'     => 'rating',
                    'value'   => 0,
                    'compare' => '>',
                    'type'    => 'NUMERIC',
                ),
            ),
        )
    );

    if ( empty( $comments ) ) {
        return $data;
    }

    $reviews = array();

    foreach ( $comments as $comment ) {

        $rating = (int) get_comment_meta(
            $comment->comment_ID,
            'rating',
            true
        );

        if (
            $rating < 1 ||
            $rating > 5
        ) {
            continue;
        }

        $author = trim(
            wp_strip_all_tags(
                $comment->comment_author
            )
        );

        $body = trim(
            wp_strip_all_tags(
                $comment->comment_content
            )
        );

        /*
         * Google برای Review باکیفیت،
         * متن و نویسنده واقعی می‌خواهد.
         */
        if (
            '' === $author ||
            '' === $body
        ) {
            continue;
        }

        $reviews[] = array(
            '@type' => 'Review',

            'author' => array(
                '@type' => 'Person',
                'name'  => $author,
            ),

            'datePublished' =>
                get_comment_date(
                    'c',
                    $comment
                ),

            'reviewBody' => $body,

            'reviewRating' => array(
                '@type'       => 'Rating',
                'ratingValue' => $rating,
                'bestRating'  => 5,
                'worstRating' => 1,
            ),
        );
    }

    if ( ! empty( $reviews ) ) {
        $data['review'] = $reviews;
    }

    return $data;
}

/*
 * Keshavarz20 Organization Address Schema
 * دفتر مرکزی: شیراز، میدان معلم
 */

add_filter(
    'wpseo_schema_organization',
    'keshavarz20_add_real_address_to_organization',
    40,
    2
);

function keshavarz20_add_real_address_to_organization(
    $data,
    $context
) {

    if ( ! is_array( $data ) ) {
        return $data;
    }

    $data['address'] = array(
        '@type'           => 'PostalAddress',
        'streetAddress'   => 'میدان معلم',
        'addressLocality' => 'شیراز',
        'addressRegion'   => 'فارس',
        'postalCode'      => '7185915694',
        'addressCountry'  => 'IR',
    );

    return $data;
}

add_action( 'template_redirect', function () {
    if ( is_admin() || ( function_exists( 'wp_doing_ajax' ) && wp_doing_ajax() ) ) {
        return;
    }

    $is_commerce_page =
        ( function_exists( 'is_product' ) && is_product() ) ||
        ( function_exists( 'is_shop' ) && is_shop() ) ||
        ( function_exists( 'is_product_category' ) && is_product_category() ) ||
        ( function_exists( 'is_product_tag' ) && is_product_tag() ) ||
        ( function_exists( 'is_product_taxonomy' ) && is_product_taxonomy() );

    if ( ! $is_commerce_page ) {
        return;
    }

    ob_start( function ( $html ) {
        return str_replace( 'فروشگاه اینترنتی باران', 'کشاورز بیست', $html );
    } );
}, 0 );

/**
 * K20 Seller Organization Entity Link v1
 * P0-C schema consistency fix.
 * Reuses the canonical Yoast Organization entity for Offer.seller.
 */

function k20_canonical_seller_reference() {
    return array(
        '@id' => 'https://keshavarz20.com/#organization',
    );
}

add_filter( 'woocommerce_structured_data_product_offer', function ( $offer, $product ) {
    if ( ! is_array( $offer ) ) {
        return $offer;
    }

    $offer['seller'] = k20_canonical_seller_reference();
    return $offer;
}, 10000, 2 );

add_filter( 'wpseo_schema_offer', function ( $offer, $variation, $product ) {
    if ( ! is_array( $offer ) ) {
        return $offer;
    }

    $offer['seller'] = k20_canonical_seller_reference();
    return $offer;
}, 10000, 3 );
